window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-116"]=[{"id":"set2-wCSh4xXp","fingerprint":"4997ae6afc2524f1","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Ce fenomen fiziologic reprezintă erupția dentară?","options":[{"id":"A","text":"Migrarea dinților din zona osoasă a maxilarelor către suprafața ocluzală."},{"id":"B","text":"Un proces biologic simplu, derivat din termenul latin „erumpere”, care înseamnă „a străpunge”."},{"id":"C","text":"Deplasarea exclusiv axială a dinților în interiorul osului maxilar."},{"id":"D","text":"Formarea completă a joncțiunii dento-gingivale după atingerea planului de ocluzie."},{"id":"E","text":"Procesul de resorbție și apoziție a osului alveolar, independent de dezvoltarea dintelui."}],"correct":["A"],"pages":[367],"source":"set-2"},{"id":"set2-VJLDntsP","fingerprint":"1800780b24046e31","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Conform uneia dintre teoriile actuale privind mecanismul erupției dentare, ce generează forța care deplasează dintele?","options":[{"id":"A","text":"Procesele de apoziție și resorbție a osului alveolar."},{"id":"B","text":"Influența genetică directă asupra mișcării axiale."},{"id":"C","text":"Presiunea exercitată de creșterea rădăcinii dentare."},{"id":"D","text":"Creșterea în volum a coroanei dentare în etapa preeruptivă."},{"id":"E","text":"Proprietatea contractilă a fibroblastelor din ligamentul periodontal."}],"correct":["E"],"pages":[367],"source":"set-2"},{"id":"set2-cQoSXqB5","fingerprint":"2f9512204bde7432","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Care este o caracteristică distinctivă a erupției dinților permanenți în comparație cu cea a dinților temporari?","options":[{"id":"A","text":"Mecanismele de erupție sunt fundamental diferite între cele două dentiții."},{"id":"B","text":"Erupția dinților permanenți este mai lentă, cu o amplitudine mai mare și mai îndelungată."},{"id":"C","text":"Tiparul erupției este simetric la dinții temporari, dar asimetric la cei permanenți."},{"id":"D","text":"Erupția dinților permanenți este mai rapidă și de o durată mai scurtă."},{"id":"E","text":"Amplitudinea erupției este mai mică la dinții permanenți."}],"correct":["B"],"pages":[367],"source":"set-2"},{"id":"set2-JpOvcXvz","fingerprint":"d0075fbe800b9c9d","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Ce caracterizează tiparul erupției dentare la ambele dentiții?","options":[{"id":"A","text":"Este un proces simetric, iar diferențele de erupție între dinții omologi nu depășesc 2-4 luni."},{"id":"B","text":"Este un proces asimetric, cu variații de peste 6 luni între dinții omologi."},{"id":"C","text":"Viteza de erupție este identică pentru toți dinții dintr-o arcadă."},{"id":"D","text":"Este un proces simetric, dar numai pentru dentiția temporară."},{"id":"E","text":"Dinții erup simultan, fără o ordine specifică."}],"correct":["A"],"pages":[367],"source":"set-2"},{"id":"set2-zgHgjwUQ","fingerprint":"ce9a8f2d153caab0","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care dintre următoarele afirmații descriu corect etapa preeruptivă (intraosoasă) a erupției dentare?","options":[{"id":"A","text":"Modificările osului alveolar joacă un rol esențial și determinant în această etapă."},{"id":"B","text":"La finalul acestei etape, rădăcina dentară este formată aproximativ între 1/3 și 1/2 din lungimea ei."},{"id":"C","text":"Creșterea în volum a coroanei dentare determină un proces de resorbție în masa alveolară înconjurătoare."},{"id":"D","text":"Această etapă corespunde perioadei de dezvoltare a germenului dentar."},{"id":"E","text":"Mișcările predominant axiale ale dintelui încep din momentul în care coroana este complet mineralizată."}],"correct":["B","C","D","E"],"pages":[367],"source":"set-2"},{"id":"set2-zV2xqzNS","fingerprint":"4b8e4a8f16fe0394","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"În ce stadiu de dezvoltare se află dintele la debutul mișcărilor predominant axiale din etapa preeruptivă?","options":[{"id":"A","text":"Coroana este complet mineralizată, iar formarea rădăcinii este doar începută."},{"id":"B","text":"Rădăcina este formată în proporție de 1/2 din lungimea sa."},{"id":"C","text":"Atât coroana, cât și rădăcina sunt complet mineralizate."},{"id":"D","text":"Coroana este încă în curs de mineralizare."},{"id":"E","text":"Germenele dentar nu a început încă procesul de mineralizare."}],"correct":["A"],"pages":[367],"source":"set-2"},{"id":"set2-fhJiMQwJ","fingerprint":"0b15f3238aae42c7","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"În ce stadiu de dezvoltare se află rădăcina dentară la sfârșitul etapei preeruptive (intraosoase)?","options":[{"id":"A","text":"Creșterea volumului coroanei dentare determină un proces de resorbție în masa alveolară din jur."},{"id":"B","text":"Formarea sa este doar începută."},{"id":"C","text":"Este formată aproximativ 1/3 până la 1/2 din lungimea sa."},{"id":"D","text":"Formarea sa nu a început încă, fiind mineralizată doar coroana."},{"id":"E","text":"Este complet formată, dar apexul este încă deschis."}],"correct":["C"],"pages":[368],"source":"set-2"},{"id":"set2-wuyZaA84","fingerprint":"5b494dd8136498d6","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care dintre următoarele afirmații caracterizează etapa eruptivă (prefuncțională) a erupției dentare?","options":[{"id":"A","text":"Mișcările de deplasare sunt exclusiv axiale, fără componente meziale sau transversale."},{"id":"B","text":"Mecanismele principale implicate sunt procesele de apoziție și resorbție reglate genetic."},{"id":"C","text":"Cuprinde o subetapă intraosoasă și o subetapă extraosoasă, preocluzală."},{"id":"D","text":"Elementul determinant în asigurarea deplasării dinților îl constituie modificările osului alveolar."},{"id":"E","text":"Se încheie odată cu articularea dintelui respectiv cu dinții vecini și antagoniști."}],"correct":["C","D","E"],"pages":[368],"source":"set-2"},{"id":"set2-j_xWNc9d","fingerprint":"44be9a7463e8c087","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Ce procese continuă să aibă loc în etapa posteruptivă, după ce dintele a atins planul de ocluzie?","options":[{"id":"A","text":"Deplasările dentare încetează complet datorită finalizării creșterii rădăcinii."},{"id":"B","text":"Formarea rădăcinii în zona apicală continuă pentru o perioadă de 1-4 ani."},{"id":"C","text":"Procesul alveolar continuă să crească în înălțime la începutul etapei."},{"id":"D","text":"Mecanismele principale implicate sunt procesele de apoziție și resorbție reglate genetic."},{"id":"E","text":"Au loc deplasări limitate ale dinților ca rezultat al restructurării rapoartelor ocluzale."}],"correct":["B","C","E"],"pages":[368],"source":"set-2"},{"id":"set2-hc8zf8HF","fingerprint":"78577c7d978d0271","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Care este o diferență fundamentală între remodelarea osului și remodelarea cementului și dentinei după încheierea perioadei formative?","options":[{"id":"A","text":"Mecanismele principale implicate sunt procesele de apoziție și resorbție reglate genetic."},{"id":"B","text":"Osul se poate remodela permanent prin apoziție și resorbție, în timp ce cementul și dentina se remodelează doar prin apoziții."},{"id":"C","text":"Osul are origine ectomezodermală, ceea ce îi permite remodelarea, spre deosebire de cement și dentină, care au origine mezodermală."},{"id":"D","text":"Smalțul, cementul și dentina își pierd complet capacitatea de remodelare, spre deosebire de os."},{"id":"E","text":"Remodelarea osului este limitată la apoziție, în timp ce remodelarea dentinei implică atât apoziție, cât și resorbție."}],"correct":["B"],"pages":[368],"source":"set-2"},{"id":"set2-jhrg2XVo","fingerprint":"93b27bd6f89d57f7","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care sunt aspectele de importanță practică ce decurg din caracteristicile structurale ale dinților după încheierea dezvoltării lor?","options":[{"id":"A","text":"Remodelarea continuă a smalțului permite adaptarea la modificările ocluzale."},{"id":"B","text":"Tulburările metabolice sistemice pot induce resorbția dentinei și a cementului."},{"id":"C","text":"Mecanismele principale implicate sunt procesele de apoziție și resorbție reglate genetic."},{"id":"D","text":"Pierderile de substanță dentară, precum cele din caria dentară, nu beneficiază de reparații pe cale generală."},{"id":"E","text":"Forma dinților și conținutul lor mineral nu pot fi afectate de tulburări sistemice generale."}],"correct":["D","E"],"pages":[368],"source":"set-2"},{"id":"set2-Rwn5MRTW","fingerprint":"b22962d1d2bb1827","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Referitor la variațiile normale ale erupției dinților temporari, care dintre următoarele afirmații sunt adevărate?","options":[{"id":"A","text":"Mecanismele principale implicate sunt procesele de apoziție și resorbție reglate genetic."},{"id":"B","text":"Primii dinți erup, de regulă, mai devreme la băieți decât la fete."},{"id":"C","text":"La copiii cu greutate mare la naștere, erupția incisivilor poate fi precoce."},{"id":"D","text":"Fetele prezintă un avans semnificativ și constant în toate secvențele de erupție dentară."},{"id":"E","text":"Greutatea mare la naștere influențează în mod constant și erupția molarilor temporari."}],"correct":["B","C"],"pages":[368],"source":"set-2"},{"id":"set2-B-uV3QFD","fingerprint":"91e5f2d79d791db5","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care dintre următorii factori pot influența în mod normal momentul erupției dinților temporari?","options":[{"id":"A","text":"Un număr crescut de nașteri anterioare ale mamei determină erupția precoce a primilor dinți."},{"id":"B","text":"Greutatea mare la naștere este asociată cu erupția precoce a incisivilor."},{"id":"C","text":"Primii dinți erup, în general, mai târziu la băieți decât la fete."},{"id":"D","text":"Nașterile premature sunt însoțite de întârzieri ale erupției primilor dinți."},{"id":"E","text":"Erupția dentară are loc mai devreme dacă mama este mai tânără la primul copil."}],"correct":["B","D","E"],"pages":[369],"source":"set-2"},{"id":"set2-6aIXqGlc","fingerprint":"c829c4b30c0aca85","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care dintre următoarele condiții patologice pot determina întârzieri în erupția dinților temporari?","options":[{"id":"A","text":"Rubeola prenatală"},{"id":"B","text":"Luesul congenital"},{"id":"C","text":"Rahitismul"},{"id":"D","text":"Sindromul Down"},{"id":"E","text":"Febrele eruptive"}],"correct":["A","B","C","D"],"pages":[369],"source":"set-2"},{"id":"set2-h1COQHeN","fingerprint":"b53b62899df804d6","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"În contextul anomaliilor cromozomiale, ce secvență neobișnuită a erupției dinților temporari poate fi observată?","options":[{"id":"A","text":"Absența erupției incisivilor centrali până la 2 ani."},{"id":"B","text":"Erupția primului molar temporar înaintea incisivului lateral."},{"id":"C","text":"Erupția simultană a incisivilor laterali și a caninilor."},{"id":"D","text":"Erupția caninului înaintea primului molar temporar."},{"id":"E","text":"Accelerarea erupției molarilor secunzi temporari."}],"correct":["B"],"pages":[369],"source":"set-2"},{"id":"set2-iuhdcRd3","fingerprint":"3c7f7b0ddc4719f4","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care dintre următoarele afirmații despre variațiile normale ale erupției dinților permanenți sunt corecte?","options":[{"id":"A","text":"La fete, dinții permanenți erup în medie cu 3-5 luni mai devreme decât la băieți."},{"id":"B","text":"Condițiile socio-economice precare sunt asociate cu o erupție dentară permanentă mai precoce."},{"id":"C","text":"Copiii indieni prezintă erupții dentare mai precoce decât cei europeni pentru primele grupe dentare."},{"id":"D","text":"Copiii din mediul urban tind să aibă o erupție dentară mai accelerată comparativ cu cei din mediul rural."},{"id":"E","text":"Copiii din zonele cu climat temperat prezintă o erupție dentară mai accelerată decât cei din zona tropicală."}],"correct":["A","D"],"pages":[369],"source":"set-2"},{"id":"set2-v84S-ZvQ","fingerprint":"e1756d7a9c059e5b","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Care este efectul tendinței seculare asupra erupției dinților permanenți?","options":[{"id":"A","text":"Molarii secunzi, caninii și primii premolari mandibulari erup mai devreme."},{"id":"B","text":"Molarii trei și primii premolari maxilari erup mai devreme."},{"id":"C","text":"Doar incisivii și primii molari permanenți sunt afectați de această tendință."},{"id":"D","text":"Toți dinții permanenți erup mai devreme cu aproximativ 6 luni."},{"id":"E","text":"Perioada de erupție a dinților permanenți a rămas neschimbată în timp."}],"correct":["A"],"pages":[369],"source":"set-2"},{"id":"set2-_9mX5ii8","fingerprint":"18601431fb433513","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Ce influență are activitatea glandelor endocrine asupra erupției dinților permanenți?","options":[{"id":"A","text":"Activitatea glandelor endocrine influențează doar ritmul, nu și viteza de erupție."},{"id":"B","text":"Deficitul hormonului de creștere din lobul anterior al hipofizei accelerează erupția."},{"id":"C","text":"Pubertatea precoce este asociată întotdeauna cu întârzieri în erupția dentară."},{"id":"D","text":"Hiperactivitatea tiroidei poate produce accelerări în erupția dentară."},{"id":"E","text":"Hipofuncția tiroidiană determină o erupție precoce a dinților permanenți."}],"correct":["D"],"pages":[369],"source":"set-2"},{"id":"set2-OWGKAs1J","fingerprint":"8bdda7a3919027ea","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care dintre următoarele boli genetice sunt menționate ca fiind asociate cu variații patologice ale erupției dinților permanenți?","options":[{"id":"A","text":"Rubeola prenatală"},{"id":"B","text":"Sindromul Turner"},{"id":"C","text":"Osteopetroza"},{"id":"D","text":"Disostoza cleidocraniană"},{"id":"E","text":"Rahitismul"}],"correct":["B","C","D"],"pages":[369],"source":"set-2"},{"id":"set2-qyle5C_5","fingerprint":"e87f4f5d84526bff","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care dintre următoarele afecțiuni endocrine pot influența ritmul și viteza erupției dentare?","options":[{"id":"A","text":"Deficitul tiroidian determină accelerări remarcabile în erupția dentară."},{"id":"B","text":"Deficitul de hormon de creștere determină întârzieri în erupția dentară."},{"id":"C","text":"Hipersecreția hormonului de creștere produce accelerări în erupția dentară."},{"id":"D","text":"Modificările endocrine sunt frecvent asociate cu pubertatea precoce sau întârziată."},{"id":"E","text":"Hiperactivitatea tiroidiană produce accelerări în erupția dentară."}],"correct":["B","C","D","E"],"pages":[370],"source":"set-2"},{"id":"set2-PBPwO8jJ","fingerprint":"aa4dffe58dcc4552","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Ce afecțiuni genetice pot întârzia apariția dinților permanenți și perturba secvența erupției acestora?","options":[{"id":"A","text":"Rahitismul"},{"id":"B","text":"Angioamele feței"},{"id":"C","text":"Sindromul Down"},{"id":"D","text":"Disostoza cleidocraniană"},{"id":"E","text":"Sindromul Turner"}],"correct":["C","D","E"],"pages":[370],"source":"set-2"},{"id":"set2-JMxqXDgi","fingerprint":"3b7ced3c46a39eb1","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Care este efectul complicațiilor gangrenei dinților temporari asupra erupției succesorilor permanenți?","options":[{"id":"A","text":"Întârzierea erupției din cauza anchilozei dento-alveolare."},{"id":"B","text":"Erupția precoce a succesorilor, datorită congestiei din procesul de osteită."},{"id":"C","text":"Întârzierea erupției prin organizarea unui capac fibros."},{"id":"D","text":"Niciun efect asupra dintelui succesor."},{"id":"E","text":"Oprirea completă a erupției dintelui succesor."}],"correct":["B"],"pages":[370],"source":"set-2"},{"id":"set2-E_QO-sgC","fingerprint":"0a3ca2a6009beb78","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care dintre următoarele reprezintă obstacole locale ce pot întârzia erupția unuia sau a mai multor dinți permanenți?","options":[{"id":"A","text":"Deplasarea dinților vecini cu limitarea spațiului de erupție."},{"id":"B","text":"Organizarea unui capac fibros prin pierderea foarte timpurie a dintelui temporar."},{"id":"C","text":"Anchiloza dento-alveolară post-traumatică."},{"id":"D","text":"Creșterea fluxului sanguin în angioamele feței."},{"id":"E","text":"Congestia din procesul de osteită."}],"correct":["A","B"],"pages":[370],"source":"set-2"},{"id":"set2-H7xa7GsO","fingerprint":"bee6c17f8544274d","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Ce reprezintă vârsta dentară și care sunt metodele de apreciere a acesteia?","options":[{"id":"A","text":"Aprecierea se poate realiza în funcție de gradul de mineralizare dentară determinat radiologic."},{"id":"B","text":"Aprecierea se poate realiza în funcție de numărul dinților erupți."},{"id":"C","text":"Reprezintă un indicator care exprimă gradul de maturare dentară al unui individ la un moment dat."},{"id":"D","text":"Este un concept utilizat exclusiv în antropologie."},{"id":"E","text":"Vârsta dentară este întotdeauna concordantă cu vârsta cronologică și cea osoasă."}],"correct":["A","B","C"],"pages":[370],"source":"set-2"},{"id":"set2-oE-r27Y4","fingerprint":"8606f48565bea467","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Referitor la dinamica erupției dinților temporari, care sunt afirmațiile corecte?","options":[{"id":"A","text":"Erupția completă a dentiției temporare se finalizează la vârsta de 1 an și jumătate."},{"id":"B","text":"Ultimii dinți temporari care erup sunt molarii secunzi superiori, la vârsta de 2 ani și jumătate."},{"id":"C","text":"Primii dinți temporari care apar în cavitatea bucală sunt incisivii centrali superiori la vârsta de 6 luni."},{"id":"D","text":"Primii molari temporari erup înaintea incisivilor laterali."},{"id":"E","text":"În medie, la fiecare 6 luni erupe câte un grup dentar."}],"correct":["B","E"],"pages":[370],"source":"set-2"},{"id":"set2-Z4KVvjEW","fingerprint":"612b8bdf599592a0","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Care este ordinea corectă de erupție a dinților temporari, conform datelor clasice?","options":[{"id":"A","text":"Incisivii centrali superiori -&gt; Incisivii centrali inferiori -&gt; Primii molari superiori -&gt; Primii molari inferiori"},{"id":"B","text":"Primii molari inferiori -&gt; Primii molari superiori -&gt; Incisivii laterali inferiori -&gt; Incisivii laterali superiori"},{"id":"C","text":"Incisivii centrali inferiori -&gt; Caninii inferiori -&gt; Primii molari inferiori -&gt; Molarii secunzi inferiori"},{"id":"D","text":"Incisivii centrali inferiori -&gt; Incisivii centrali superiori -&gt; Incisivii laterali superiori -&gt; Incisivii laterali inferiori"},{"id":"E","text":"Molarii secunzi inferiori -&gt; Molarii secunzi superiori -&gt; Caninii inferiori -&gt; Caninii superiori"}],"correct":["D"],"pages":[370],"source":"set-2"},{"id":"set2-XWoxms5f","fingerprint":"2adfe198bcb8ab0b","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care dintre următoarele afirmații referitoare la regulile generale ale erupției dinților temporari sunt corecte?","options":[{"id":"A","text":"Incisivii laterali superiori reprezintă o excepție, eruptând înaintea incisivilor laterali inferiori."},{"id":"B","text":"Erupția dinților temporari se desfășoară întotdeauna strict în ordinea poziției lor pe arcadă."},{"id":"C","text":"În mod tipic, dinții temporari mandibulari erup înaintea celor maxilari."},{"id":"D","text":"Primii molari temporari erup înaintea caninilor."},{"id":"E","text":"Caninii temporari erup înaintea primilor molari temporari."}],"correct":["A","C","D"],"pages":[371],"source":"set-2"},{"id":"set2-Lp3vl3t8","fingerprint":"5329c5460cab9a39","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Care este intervalul de vârstă asociat cu etapa a III-a a erupției dinților temporari?","options":[{"id":"A","text":"6-30 luni, corespunzând întregului proces de erupție."},{"id":"B","text":"18-24 luni, corespunzând erupției caninilor."},{"id":"C","text":"6-12 luni, corespunzând erupției incisivilor."},{"id":"D","text":"12-18 luni, corespunzând erupției primilor molari."},{"id":"E","text":"24-30 luni, corespunzând erupției molarilor secunzi."}],"correct":["E"],"pages":[371],"source":"set-2"},{"id":"set2-yB-dmG21","fingerprint":"176a5af4cbaff564","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Conform regulii 6/4, câți dinți temporari sunt erupți, în medie, la vârsta de 24 de luni?","options":[{"id":"A","text":"20 dinți"},{"id":"B","text":"16 dinți"},{"id":"C","text":"8 dinți"},{"id":"D","text":"4 dinți"},{"id":"E","text":"12 dinți"}],"correct":["B"],"pages":[371],"source":"set-2"},{"id":"set2-xJ3nUCRB","fingerprint":"c41448650ed3b716","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Ce factori influențează cronologia erupției dinților temporari și care este durata lor de menținere pe arcadă?","options":[{"id":"A","text":"La băieți, primul grup de dinți erupe mai lent decât la fete."},{"id":"B","text":"Intervalul normal de erupție este între 12 și 36 de luni."},{"id":"C","text":"Incisivii temporari se mențin în funcție aproximativ 9 ani."},{"id":"D","text":"Molarii temporari se mențin în funcție aproximativ 9 ani."},{"id":"E","text":"Cronologia erupției este influențată în special de factori de mediu."}],"correct":["D"],"pages":[371],"source":"set-2"},{"id":"set2-HncSdrMu","fingerprint":"d731de23da3fe19f","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Conform cronologiei erupției dinților temporari prezentată de van Waes și Stöckli, care dinte erupe în jurul vârstei de 16 luni?","options":[{"id":"A","text":"Caninii inferiori și superiori"},{"id":"B","text":"Incisivul central superior"},{"id":"C","text":"Molarul prim superior și inferior"},{"id":"D","text":"Molarul secund superior și inferior"},{"id":"E","text":"Incisivul lateral superior și inferior"}],"correct":["C"],"pages":[371],"source":"set-2"},{"id":"set2-hHsQGGjG","fingerprint":"74ea160e2594cc72","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Ce variație a erupției dinților temporari nu este considerată a avea semnificație patologică?","options":[{"id":"A","text":"Absența erupției oricărui dinte la vârsta de 12 luni."},{"id":"B","text":"O variație cu 1-2 luni în afara intervalelor considerate normale."},{"id":"C","text":"Erupția primului dinte la 3 luni."},{"id":"D","text":"O întârziere de 6 luni față de intervalele standard."},{"id":"E","text":"O erupție mai rapidă cu 5 luni."}],"correct":["B"],"pages":[371],"source":"set-2"},{"id":"set2-8FiFqZAg","fingerprint":"52903a62f89a66d9","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care sunt criteriile care definesc erupția întârziată a dinților temporari?","options":[{"id":"A","text":"Primul dinte temporar erupe înaintea vârstei de 4 luni."},{"id":"B","text":"Primul dinte temporar erupe după vârsta de 1 an."},{"id":"C","text":"Proffit consideră că o întârziere de până la șase luni este în intervalul de normalitate."},{"id":"D","text":"Ultimul dinte temporar erupe înaintea vârstei de 2 ani."},{"id":"E","text":"Ultimul dinte temporar erupe după vârsta de 3 ani."}],"correct":["B","E"],"pages":[372],"source":"set-2"},{"id":"set2-wlypS4zc","fingerprint":"cb6b1bdc9e082b76","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Conform cronologiei de erupție a dinților temporari după Proffit (2019), care este relația de erupție dintre dinții omologi de la maxilar și mandibulă?","options":[{"id":"A","text":"Molarul secund mandibular erupe înaintea celui maxilar."},{"id":"B","text":"Molarul prim maxilar și cel mandibular erup la vârste diferite."},{"id":"C","text":"Caninul maxilar erupe înaintea celui mandibular."},{"id":"D","text":"Incisivul lateral maxilar erupe înaintea celui mandibular."},{"id":"E","text":"Incisivul central mandibular erupe înaintea celui maxilar."}],"correct":["A","C","D","E"],"pages":[372],"source":"set-2"},{"id":"set2-Xz0ja-4T","fingerprint":"4da5e4f8b5b3e111","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Ce dinți temporari erup în etapa a II-a de erupție, conform datelor utilizate în România?","options":[{"id":"A","text":"Incisivul central inferior"},{"id":"B","text":"Molarul I superior"},{"id":"C","text":"Molarul I inferior"},{"id":"D","text":"Molarul II superior"},{"id":"E","text":"Caninul superior"}],"correct":["B","C","E"],"pages":[372],"source":"set-2"},{"id":"set2-s8BGufb7","fingerprint":"7a5b2b5e7bdac8c3","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care este definiția dinților natali și a celor neonatali?","options":[{"id":"A","text":"Dinții natali sunt întotdeauna supranumerari, iar cei neonatali sunt dinți temporari normali."},{"id":"B","text":"Dinții neonatali sunt prezenți la naștere, iar cei natali erup în prima lună de viață."},{"id":"C","text":"Ambii termeni se referă la dinții care erup în primele 6 luni de viață."},{"id":"D","text":"Dinții natali sunt prezenți la naștere, iar cei neonatali erup în prima lună de viață."},{"id":"E","text":"Termenul 'dinți congenitali' este un sinonim pentru dinții natali și neonatali."}],"correct":["D","E"],"pages":[372],"source":"set-2"},{"id":"set2-fuylVBHC","fingerprint":"533abb0127f228f5","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care dintre următoarele sunt considerate cauze posibile ale erupției dinților natali și neonatali?","options":[{"id":"A","text":"Luesul congenital."},{"id":"B","text":"O poziție foarte superficială a germenului dentar, imediat sub mucoasa bucală."},{"id":"C","text":"Transmiterea ereditară."},{"id":"D","text":"O dezvoltare încetinită a germenului dentar."},{"id":"E","text":"Tulburări endocrine și deficiențe alimentare."}],"correct":["A","B","C","E"],"pages":[372],"source":"set-2"},{"id":"set2-t2d06PFb","fingerprint":"fba8795f7b859ca8","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"În ce interval de vârstă are loc etapa a II-a de înlocuire a dinților temporari cu cei permanenți și ce dinți sunt implicați?","options":[{"id":"A","text":"La vârsta de 9 ani, erup caninul inferior și primul premolar superior."},{"id":"B","text":"Între 11 și 12 ani, implicând doar caninul superior și al doilea premolar inferior."},{"id":"C","text":"Între 6 și 9 ani, implicând înlocuirea incisivilor."},{"id":"D","text":"Între 9 și 12 ani, implicând înlocuirea zonei de sprijin."},{"id":"E","text":"Între 6 și 13 ani, implicând toți dinții cu excepția molarului de minte."}],"correct":["D"],"pages":[372],"source":"set-2"},{"id":"set2-4zCCuP_N","fingerprint":"38969e19bc77a178","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care este secvența de erupție a dinților permanenți în intervalul de vârstă 9-12 ani, conform cronologiei clasice?","options":[{"id":"A","text":"La 11-12 ani erup caninul inferior și primul premolar superior."},{"id":"B","text":"La 11-12 ani erup al doilea premolar inferior și caninul superior."},{"id":"C","text":"La 10-11 ani erup primul premolar inferior și al doilea premolar superior."},{"id":"D","text":"Caninul inferior erupe înaintea primului premolar inferior."},{"id":"E","text":"La 10-11 ani erup incisivul lateral superior și caninul inferior."}],"correct":["B","C","D"],"pages":[372],"source":"set-2"},{"id":"set2-4KcZJA7b","fingerprint":"e0dfaaafb0b6924e","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Ce dinți permanenți erup primii, marcând începutul perioadei de înlocuire a dinților temporari?","options":[{"id":"A","text":"Incisivul lateral inferior"},{"id":"B","text":"Primul premolar superior"},{"id":"C","text":"Caninul inferior"},{"id":"D","text":"Incisivul central superior"},{"id":"E","text":"Incisivul central inferior"}],"correct":["E"],"pages":[372],"source":"set-2"},{"id":"set2-feaC1-vz","fingerprint":"e1e30a9a626988bd","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care dintre următoarele fenomene se observă la sfârșitul perioadei dentiției temporare, precedând erupția dinților permanenți?","options":[{"id":"A","text":"O micșorare a arcului frontal datorită resorbției osoase."},{"id":"B","text":"O abraziune fiziologică la nivelul dinților temporari."},{"id":"C","text":"Apariția unei distalizări fiziologice a mandibulei."},{"id":"D","text":"O ușoară mezializare a mandibulei."},{"id":"E","text":"O mărire a arcului frontal cu apariția de treme între dinți."}],"correct":["B","D","E"],"pages":[373],"source":"set-2"},{"id":"set2-5400cbgv","fingerprint":"612109df4a5afcf5","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care dintre următoarele afirmații referitoare la regulile generale ale erupției dinților permanenți sunt adevărate?","options":[{"id":"A","text":"Dinții erup mai rapid la fete comparativ cu băieții."},{"id":"B","text":"Primul dinte permanent care erupe este, de regulă, primul molar inferior."},{"id":"C","text":"În cadrul aceluiași grup dentar, dinții superiori erup întotdeauna înaintea celor inferiori."},{"id":"D","text":"Erupția dinților permanenți se desfășoară în două etape principale și o etapă secundară."},{"id":"E","text":"Cronologia erupției este influențată în principal de factori genetici, cu variații minime date de mediu."}],"correct":["A","B","D"],"pages":[373],"source":"set-2"},{"id":"set2-GREdV0lE","fingerprint":"d7ef6a5539512975","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Ce grup de dinți erupe în prima etapă principală a erupției dentiției permanente, care se desfășoară între 6 și 9 ani?","options":[{"id":"A","text":"Doar molarii de minte."},{"id":"B","text":"Premolarii și caninii."},{"id":"C","text":"Incisivii și primii molari permanenți."},{"id":"D","text":"Doar primii molari și incisivii centrali."},{"id":"E","text":"Caninii, premolarii și molarii secunzi."}],"correct":["C"],"pages":[373],"source":"set-2"},{"id":"set2-sZPmVcME","fingerprint":"513ccf9e35c374e5","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Care grup dentar constituie o excepție de la regula generală conform căreia dinții inferiori erup înaintea celor superiori omologi?","options":[{"id":"A","text":"Premolarii maxilari"},{"id":"B","text":"Incisivii centrali"},{"id":"C","text":"Caninii"},{"id":"D","text":"Primii molari"},{"id":"E","text":"Molarii secunzi"}],"correct":["A"],"pages":[373],"source":"set-2"},{"id":"set2-dCPuHI94","fingerprint":"2093dccf0f6c0f98","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Care este secvența de erupție a dinților în sectorul premolar-canin specifică băieților?","options":[{"id":"A","text":"Maxilar: C-Pm2-Pm1; Mandibulă: Pm2-C-Pm1"},{"id":"B","text":"Maxilar: Pm1-Pm2-C; Mandibulă: Pm1-C-Pm2"},{"id":"C","text":"Maxilar: Pm1-Pm2-C; Mandibulă: C-Pm1-Pm2"},{"id":"D","text":"Maxilar: C-Pm1-Pm2; Mandibulă: C-Pm1-Pm2"},{"id":"E","text":"Maxilar: Pm1-C-Pm2; Mandibulă: C-Pm1-Pm2"}],"correct":["B"],"pages":[373],"source":"set-2"},{"id":"set2-9nZ_qfCZ","fingerprint":"87b1d66a1315a2df","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Care este ordinea cronologică normală a erupției dinților permanenți la mandibulă, specifică populației din România?","options":[{"id":"A","text":"6, 1, 2, 3, 4, 5, 7, 8"},{"id":"B","text":"6, 1, 2, 4, 5, 3, 7, 8"},{"id":"C","text":"6, 1, 2, 4, 3, 5, 7, 8"},{"id":"D","text":"6, 2, 1, 3, 4, 5, 7, 8"},{"id":"E","text":"1, 6, 2, 3, 4, 5, 7, 8"}],"correct":["A"],"pages":[373],"source":"set-2"},{"id":"set2-PSMbLO-Z","fingerprint":"cf4a3c911704407e","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care dintre următoarele asocieri între vârstă și evenimentele eruptive din prima etapă a dentiției permanente sunt corecte?","options":[{"id":"A","text":"La 6-7 ani erup primii molari și incisivii centrali inferiori."},{"id":"B","text":"La 7-8 ani erup incisivii centrali superiori și incisivii laterali inferiori."},{"id":"C","text":"La 6-7 ani erup caninii inferiori."},{"id":"D","text":"La 8-9 ani erup incisivii laterali superiori."},{"id":"E","text":"La 8-9 ani erup primii premolari."}],"correct":["A","B","D"],"pages":[373],"source":"set-2"},{"id":"set2-88bbruah","fingerprint":"97d9cc8694d65fba","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Care segment dentar este considerat a fi cel mai perturbat în ceea ce privește ordinea și cronologia erupției?","options":[{"id":"A","text":"Segmentul primilor molari permanenți."},{"id":"B","text":"Segmentul molarilor secunzi."},{"id":"C","text":"Segmentul molarilor de minte."},{"id":"D","text":"Segmentul incisivilor."},{"id":"E","text":"Segmentul caninilor și premolarilor."}],"correct":["E"],"pages":[373],"source":"set-2"},{"id":"set2-CodVE4Py","fingerprint":"44adc2cfab8dae1c","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care dintre următoarele sunt considerate variante ale ordinii de erupție în prima etapă a dentiției permanente?","options":[{"id":"A","text":"Primii premolari erup înaintea incisivilor laterali superiori."},{"id":"B","text":"Incisivii centrali inferiori erup primii, urmați de molarii de 6 ani."},{"id":"C","text":"Incisivii centrali superiori erup întotdeauna înaintea celor inferiori."},{"id":"D","text":"Molarii 1 erup primii și apoi incisivii centrali inferiori."},{"id":"E","text":"Molarii de 6 ani erup simultan cu incisivii centrali inferiori."}],"correct":["B","D","E"],"pages":[373],"source":"set-2"},{"id":"set2-boMjDfjL","fingerprint":"36851f08e9152dc1","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"La ce vârstă erupe caninul permanent maxilar la băieți?","options":[{"id":"A","text":"10-11 ani"},{"id":"B","text":"12-13 ani"},{"id":"C","text":"11-13 ani"},{"id":"D","text":"9-10 ani"},{"id":"E","text":"11-12 ani"}],"correct":["C"],"pages":[374],"source":"set-2"},{"id":"set2-dzrfQlW4","fingerprint":"53b96f6747446da1","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Conform cronologiei erupției dentare la fete, care este secvența corectă pentru arcada mandibulară?","options":[{"id":"A","text":"Canin (9-10 ani), urmat de Primul Premolar (10-11 ani), urmat de Al Doilea Premolar (11-12 ani)"},{"id":"B","text":"Primul Premolar (9-10 ani), urmat de Al Doilea Premolar (10-11 ani), urmat de Canin (11-13 ani)"},{"id":"C","text":"Canin (9-10 ani), urmat de Al Doilea Premolar (11-12 ani), urmat de Primul Premolar (10-11 ani)"},{"id":"D","text":"Canin (9-10 ani), urmat de Al Doilea Premolar (11-12 ani), urmat de Primul Premolar (10-11 ani)"},{"id":"E","text":"Primul Premolar (9-10 ani), urmat de Canin (10-11 ani), urmat de Al Doilea Premolar (11-12 ani)"}],"correct":["A"],"pages":[374],"source":"set-2"},{"id":"set2-GppGvCL5","fingerprint":"f3d5eaab9ecb682a","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care dintre următoarele afirmații privind cronologia erupției dinților permanenți sunt corecte?","options":[{"id":"A","text":"Primul premolar mandibular erupe mai târziu la băieți decât la fete."},{"id":"B","text":"La fete, primul premolar maxilar erupe înaintea caninului maxilar."},{"id":"C","text":"Molarul 2, atât maxilar cât și mandibular, erupe 13-14 ani strict la băieți."},{"id":"D","text":"La băieți, caninul mandibular erupe înaintea celui maxilar."},{"id":"E","text":"Molarul 2, atât maxilar cât și mandibular, erupe 13-14 ani strict la fete."}],"correct":["B","D"],"pages":[374],"source":"set-2"},{"id":"set2-sDJH2dlh","fingerprint":"7e471d4910f71bf5","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care afirmații despre erupția celui de-al doilea premolar (Pm2) și celui de-al doilea molar (M2) sunt adevărate?","options":[{"id":"A","text":"La băieți, al doilea premolar (Pm2) maxilar erupe mai devreme decât cel mandibular."},{"id":"B","text":"Intervalul de erupție pentru al doilea molar (M2) este identic (12-13 ani) pentru băieți și fete, atât la maxilar, cât și la mandibulă."},{"id":"C","text":"Al doilea premolar (Pm2) erupe la aceeași vârstă (11-12 ani) la fete, indiferent de arcadă."},{"id":"D","text":"Intervalul de erupție pentru al doilea molar (M2) este identic (6-7 ani) pentru băieți și fete, atât la maxilar, cât și la mandibulă."},{"id":"E","text":"La fete, al doilea premolar (Pm2) mandibular erupe mai devreme decât la băieți."}],"correct":["A","B","C"],"pages":[374],"source":"set-2"},{"id":"set2-lPoocFa5","fingerprint":"e85411365f3c8561","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care sunt caracteristicile sechestrului de erupție?","options":[{"id":"A","text":"Este cauzat de o neconcordanță între viteza de erupție dentară și viteza de resorbție osoasă."},{"id":"B","text":"Afectează cu predilecție incisivii temporari și caninii permanenți."},{"id":"C","text":"Radiografic, apare ca o zonă de radiotransparență omogenă deasupra coroanei dintelui."},{"id":"D","text":"Se manifestă întotdeauna prin dureri intense și necesită intervenție chirurgicală."},{"id":"E","text":"Se elimină spontan și este frecvent asimptomatic."}],"correct":["A","E"],"pages":[375],"source":"set-2"},{"id":"set2-TcT4QN6e","fingerprint":"e3a46ec0e1ce16a1","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Ce măsuri terapeutice sunt indicate în managementul gingivostomatitei?","options":[{"id":"A","text":"Tratament sistemic cu corticosteroizi în toate formele clinice."},{"id":"B","text":"Aplicarea de colutorii locale cu antibiotice, corticosteroizi și vitamine."},{"id":"C","text":"Igienizarea riguroasă a cavității bucale, inclusiv prin clătiri locale."},{"id":"D","text":"Administrarea de antibiotice pe cale generală, după caz."},{"id":"E","text":"Exclusiv administrarea de analgezice pentru controlul durerii."}],"correct":["B","C","D"],"pages":[375],"source":"set-2"},{"id":"set2-VGSotCyX","fingerprint":"dc2fa60f3d67aecb","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Ce criterii sunt utilizate concomitent pentru a diagnostica variațiile patologice sau fiziologice ale vârstei de erupție dentară?","options":[{"id":"A","text":"Criteriul simetriei erupției și criteriul secvenței de erupție."},{"id":"B","text":"Doar criteriul cronologic, comparând vârsta copilului cu vârsta medie de erupție."},{"id":"C","text":"Criteriul cronologic și criteriul dezvoltării radiculare."},{"id":"D","text":"Criteriul cronologic și prezența obstacolelor locale."},{"id":"E","text":"Criteriul dezvoltării radiculare și vârsta osoasă a copilului."}],"correct":["C"],"pages":[375],"source":"set-2"},{"id":"set2-queNq-uh","fingerprint":"2e72e3dcb0c82312","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Cum este definită erupția cronologic întârziată?","options":[{"id":"A","text":"Erupția dinților în intervalul de variabilitate considerat normal, dar aproape de limita superioară."},{"id":"B","text":"Erupția dinților cu mai mult de 2 deviații standard (DS) peste vârsta medie de erupție."},{"id":"C","text":"Erupția dinților cu mai mult de 2 deviații standard (DS) sub vârsta medie de erupție."},{"id":"D","text":"Erupția dinților la 1 an și jumătate peste vârsta medie, indiferent de tipul de dentiție."},{"id":"E","text":"Orice erupție care are loc după erupția dintelui contralateral."}],"correct":["B"],"pages":[375],"source":"set-2"},{"id":"set2-6ps1CaSd","fingerprint":"8257db726523d836","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care dintre următoarele situații sunt considerate tulburări ale ordinii de erupție în prima etapă a dentiției mixte (6-9 ani)?","options":[{"id":"A","text":"Asimetrii în erupția incisivilor centrali superiori."},{"id":"B","text":"Apariția osteosclerozelor postextracționale care întârzie erupția."},{"id":"C","text":"Erupția incisivilor laterali înaintea unuia sau ambilor centrali."},{"id":"D","text":"Erupția primilor premolari înaintea incisivilor laterali."},{"id":"E","text":"Erupția celui de-al doilea premolar înaintea primului premolar și a caninului."}],"correct":["A","C","D"],"pages":[375],"source":"set-2"},{"id":"set2-9WeEh7V_","fingerprint":"4636217e24c942e1","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Ce poate indica examenul radiologic în cazul tulburărilor de erupție din prima etapă a dentiției mixte?","options":[{"id":"A","text":"Modificarea poziției mugurelui dentar datorită unor traumatisme."},{"id":"B","text":"Erupția accelerată a întregii serii dentare."},{"id":"C","text":"Rizaliză întârziată la dintele temporar."},{"id":"D","text":"Prezența unui obstacol local, cum ar fi un dinte supranumerar."},{"id":"E","text":"Osteofibroze postextracționale."}],"correct":["A","C","D"],"pages":[375],"source":"set-2"},{"id":"set2-rBLoQXtc","fingerprint":"d3e795d4142dfdac","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Care este cauza principală a tulburărilor ordinii de erupție în a doua etapă a dentiției mixte (9-12 ani)?","options":[{"id":"A","text":"Viteza de erupție crescută a premolarilor."},{"id":"B","text":"Complicațiile periapicale ale cariilor netratate ale molarilor temporari."},{"id":"C","text":"Lipsa mugurelui dentar al premolarului doi."},{"id":"D","text":"Prezența unor formațiuni chistice sau a dinților supranumerari."},{"id":"E","text":"Traumatismele la nivelul dinților temporari."}],"correct":["B"],"pages":[375],"source":"set-2"},{"id":"set2-vK-VfSHy","fingerprint":"cabcb4ec38a47331","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Ce consecință poate avea apariția osteosclerozelor postextracționale în contextul tulburărilor de erupție din etapa a II-a a dentiției mixte?","options":[{"id":"A","text":"Crearea de spațiu suplimentar pentru alinierea corectă a caninului."},{"id":"B","text":"Erupția premolarului doi înaintea primului premolar."},{"id":"C","text":"Accelerarea erupției premolarului doi."},{"id":"D","text":"Favorizarea erupției ectopice sau a incluziei premolarului doi."},{"id":"E","text":"Distalizarea primului molar permanent."}],"correct":["D"],"pages":[375],"source":"set-2"},{"id":"set2-Nm1bI_Nx","fingerprint":"5aa15e356560d3a1","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care dintre următoarele situații clinice sunt considerate tulburări de ritm ale erupției dentare?","options":[{"id":"A","text":"Schimbarea locului pe arcadă între caninul superior și primul premolar."},{"id":"B","text":"Dinții de pe o hemiarcadă se află în infraocluzie, în timp ce pe hemiarcada opusă au erupt complet, atingând planul de ocluzie."},{"id":"C","text":"Un decalaj între vârsta dentară și cea osoasă conduce la erupția accelerată a incisivilor, generând o înghesuire tranzitorie."},{"id":"D","text":"Erupția dinților temporari debutează la 9-10 luni, dar se finalizează la 2,5 ani, cu toți dinții prezenți pe arcadă."},{"id":"E","text":"Formarea caninului superior în regiunea infraorbitară, la mare distanță de locul său normal pe arcadă."}],"correct":["B","C","D"],"pages":[376],"source":"set-2"},{"id":"set2-Rm3Ml7aK","fingerprint":"d5af0d97a4c48ce2","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Ce termen descrie situația clinică în care caninul superior își schimbă locul pe arcadă cu primul premolar?","options":[{"id":"A","text":"Infraocluzie"},{"id":"B","text":"Ectopie"},{"id":"C","text":"Heterotopie"},{"id":"D","text":"Transpoziție dentară"},{"id":"E","text":"Incluzie"}],"correct":["D"],"pages":[376],"source":"set-2"},{"id":"set2-UUfUJG_C","fingerprint":"501370d8e78cb1e8","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care dintre următoarele afirmații referitoare la tulburările de poziție dentară sunt adevărate?","options":[{"id":"A","text":"Lipsa tremelor și diastemelor fiziologice este o cauză frecventă a transpozițiilor dentare."},{"id":"B","text":"Caninul superior este dintele cel mai frecvent implicat în transpoziții, schimbându-și locul fie cu primul premolar, fie cu incisivul lateral."},{"id":"C","text":"O erupție asimetrică între hemiarcade este considerată o tulburare de poziție."},{"id":"D","text":"Malpozițiile precum ectopiile și incluziile interesează de obicei ultimii dinți din fiecare grup dentar."},{"id":"E","text":"Heterotopia se poate manifesta prin prezența molarului de minte inferior în ramura ascendentă a mandibulei."}],"correct":["B","D","E"],"pages":[376],"source":"set-2"},{"id":"set2-Dn0SBizP","fingerprint":"6558d4b10478202e","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Ce condiție definește o erupție dentară fiziologică normală?","options":[{"id":"A","text":"Un decalaj între vârsta dentară și vârsta osoasă, care accelerează erupția."},{"id":"B","text":"Concordanța dintre vârsta cronologică, vârsta osoasă și vârsta dentară."},{"id":"C","text":"Un debut al erupției la 9-10 luni, urmat de un ritm rapid de recuperare."},{"id":"D","text":"Absența tremelor și diastemelor fiziologice în perioada permutării dentare."},{"id":"E","text":"Erupția completă a dinților pe o hemiarcadă, în timp ce pe cealaltă sunt în infraocluzie."}],"correct":["B"],"pages":[376],"source":"set-2"},{"id":"set2-PtsbcJak","fingerprint":"18ff2cdc520720c9","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care dintre următoarele reprezintă structuri de susținere ce se formează concomitent cu modificările tisulare din timpul erupției dentare?","options":[{"id":"A","text":"Coroana dentară"},{"id":"B","text":"Parodonțiul"},{"id":"C","text":"Osul bazal maxilar"},{"id":"D","text":"Joncțiunea dento-gingivală"},{"id":"E","text":"Rădăcina dentară"}],"correct":["B","D","E"],"pages":[367],"source":"set-2"},{"id":"set2-UY6_FagU","fingerprint":"7521305d2851bce8","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Prin ce se diferențiază erupția dinților permanenți față de cea a dinților temporari?","options":[{"id":"A","text":"Tiparul de erupție al dinților permanenți este asimetric."},{"id":"B","text":"Amplitudinea mișcărilor este mai redusă la dinții permanenți."},{"id":"C","text":"Dinții permanenți prezintă o amplitudine mai mare a mișcărilor eruptive."},{"id":"D","text":"Erupția dinților permanenți se desfășoară într-un ritm mai lent."},{"id":"E","text":"Procesul de erupție are o durată mai îndelungată."}],"correct":["C","D","E"],"pages":[367],"source":"set-2"},{"id":"set2-MolVEAXs","fingerprint":"c1b30d15491f3685","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care sunt condițiile necesare transformării contracției fibroblastelor ligamentare în mișcare dentară, în cadrul teoriei tracțiunii ligamentului periodontal?","options":[{"id":"A","text":"Creșterea coroanei dentare"},{"id":"B","text":"Remodelarea osului"},{"id":"C","text":"Creșterea rădăcinii"},{"id":"D","text":"Remodelarea colagenului"},{"id":"E","text":"Absența resorbției osoase"}],"correct":["B","C","D"],"pages":[367],"source":"set-2"},{"id":"set2-K69X0DjP","fingerprint":"b21091a105965d0f","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Ce interval de timp reprezintă diferența maximă întâlnită între erupția dinților omologi, respectând tiparul simetric de erupție?","options":[{"id":"A","text":"6-8 luni"},{"id":"B","text":"8-12 luni"},{"id":"C","text":"1-2 luni"},{"id":"D","text":"4-6 luni"},{"id":"E","text":"2-4 luni"}],"correct":["E"],"pages":[367],"source":"set-2"},{"id":"set2-UL0yNYGm","fingerprint":"5241984fd936d3aa","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Ce fenomene și direcții de deplasare caracterizează mecanismul mișcării dintelui în cadrul erupției dentare?","options":[{"id":"A","text":"Forța de deplasare este atribuită proprietății contractile a fibroblastelor ligamentare."},{"id":"B","text":"Deplasarea dintelui se realizează în principal în direcție axială."},{"id":"C","text":"Mișcările dintelui se pot produce și în alte planuri, explicând versiunea molarilor de minte."},{"id":"D","text":"Forța de deplasare este generată de proprietatea contractilă a osteoclastelor."},{"id":"E","text":"Direcția principală de deplasare a dintelui este exclusiv transversală."}],"correct":["A","B","C"],"pages":[367],"source":"set-2"},{"id":"set2-tDherpj7","fingerprint":"f9a8c3da5532dd1e","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care dintre următoarele afirmații descriu etapa preeruptivă a erupției dentare?","options":[{"id":"A","text":"Dintele își începe mișcările predominant axiale atunci când coroana este complet mineralizată."},{"id":"B","text":"Mecanismele de producere a mișcărilor sunt reprezentate de procese de apoziție și resorbție reglate genetic."},{"id":"C","text":"La finalul acestei etape, rădăcina dentară atinge o dezvoltare de 1/3 până la 1/2 din lungimea ei."},{"id":"D","text":"Direcția deplasării este influențată decisiv de matricea funcțională reprezentată de musculatura periorală și limbă."},{"id":"E","text":"Modificările osului alveolar constituie elementul determinant al mișcărilor din această etapă, cu creșteri abundente la nivelul bazei alveolei."}],"correct":["A","B","C"],"pages":[367],"source":"set-2"},{"id":"set2-8yO6PSFD","fingerprint":"2aba14abe2555122","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Care dintre următoarele aspecte este specific etapei eruptive (prefuncționale) a dintelui?","options":[{"id":"A","text":"Cuprinde exclusiv mișcări transversale care deplasează dintele de la locul de formare intraosos."},{"id":"B","text":"Are debutul marcat de momentul atingerii planului de ocluzie."},{"id":"C","text":"Deplasările devin limitate ca urmare a restructurării permanente a rapoartelor pârghiilor dentare."},{"id":"D","text":"Elementul determinant al deplasării este reprezentat de modificările osului alveolar, cu creșteri abundente la nivelul bazei alveolei."},{"id":"E","text":"Se finalizează în momentul în care coroana dentară este complet mineralizată."}],"correct":["D"],"pages":[368],"source":"set-2"},{"id":"set2-U3YO1XQm","fingerprint":"023b28d928a2f90e","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care sunt caracteristicile etapei posteruptive (funcționale) a dintelui?","options":[{"id":"A","text":"Musculatura periorală și limba se inserează pe crestele alveolare pentru a frâna mișcările de erupție."},{"id":"B","text":"Deplasările limitate ale dinților sunt influențate de modificările ce au loc la nivelul punctelor de contact."},{"id":"C","text":"Debutează concomitent cu formarea primei treimi a rădăcinii dentare."},{"id":"D","text":"Formarea rădăcinii în zona apicală continuă pentru o perioadă de 1-4 ani după atingerea planului de ocluzie."},{"id":"E","text":"La începutul acestei etape, procesul alveolar continuă să crească în înălțime."}],"correct":["B","D","E"],"pages":[368],"source":"set-2"},{"id":"set2-gJ5qPytz","fingerprint":"72b3828ed9bba9e0","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Care dintre următoarele reprezintă subetapele ce alcătuiesc etapa eruptivă a dintelui?","options":[{"id":"A","text":"Subetapa prefuncțională și subetapa postocluzală."},{"id":"B","text":"Subetapa de mineralizare coronară și subetapa de dezvoltare a germenului."},{"id":"C","text":"Subetapa de resorbție a masei alveolare și subetapa de apoziție."},{"id":"D","text":"Subetapa mișcărilor predominant axiale și subetapa mișcărilor transversale."},{"id":"E","text":"Subetapa intraosoasă și subetapa extraosoasă, preocluzală."}],"correct":["E"],"pages":[368],"source":"set-2"},{"id":"set2-ZRYP-3nR","fingerprint":"608b6c26d49b9de9","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care sunt procesele și factorii care influențează dinamica dentară pe parcursul etapelor de erupție?","options":[{"id":"A","text":"În etapa eruptivă, direcția de deplasare este ghidată de musculatura periorală și de limbă."},{"id":"B","text":"În etapa posteruptivă, deplasările devin limitate și sunt rezultatul modificărilor la nivelul punctelor de contact și al restructurării pârghiilor dentare."},{"id":"C","text":"Atingerea planului de ocluzie determină sistarea completă a mișcărilor dentare pe arcadă."},{"id":"D","text":"În etapa eruptivă, modificările osului alveolar joacă un rol minim, fiind limitate pe pereții laterali."},{"id":"E","text":"În etapa preeruptivă, creșterea volumului coroanei determină un proces de resorbție în masa alveolară din jur."}],"correct":["A","B","E"],"pages":[367],"source":"set-2"},{"id":"set2-vYSKw-7L","fingerprint":"e7d4f78c25f00765","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care dintre următoarele afirmații referitoare la diferențele structurale și de dezvoltare dintre țesuturile dentare și cele osoase sunt adevărate?","options":[{"id":"A","text":"Smalțul își pierde legătura cu matricea formativă după perioada de formare, nebeneficiind de remodelări ulterioare."},{"id":"B","text":"Dinții au origine exclusiv ectodermală, în timp ce osul are origine mezodermală."},{"id":"C","text":"Conținutul mineral al dinților nu este modificat de tulburările sistemice generale apărute după încheierea dezvoltării acestora."},{"id":"D","text":"Osul se poate remodela în permanență, păstrând legătura cu matricea sa formativă după încheierea etapei de dezvoltare."},{"id":"E","text":"Cementul și dentina suferă procese de remodelare permanente atât prin apoziție, cât și prin resorbție."}],"correct":["A","C","D"],"pages":[368],"source":"set-2"},{"id":"set2-ULCfPL-V","fingerprint":"670f41f4875e332f","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"În care dintre următoarele condiții patologice întârzierea erupției dinților temporari se asociază cu o secvență eruptivă neobișnuită, caracterizată prin apariția primului molar temporar înaintea incisivului lateral?","options":[{"id":"A","text":"Febrele eruptive"},{"id":"B","text":"Osteopetroza"},{"id":"C","text":"Rahitismul"},{"id":"D","text":"Luesul congenital"},{"id":"E","text":"Rubeola prenatală"}],"correct":["B"],"pages":[369],"source":"set-2"},{"id":"set2--UKWFxS5","fingerprint":"ee5ae9bf86608c6c","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care sunt factorii fiziologici ce influențează cronologia și variațiile normale ale erupției dinților temporari?","options":[{"id":"A","text":"Greutatea mare la naștere determină o erupție precoce a incisivilor, dar influențează foarte rar erupția molarilor."},{"id":"B","text":"Un număr crescut de nașteri ale mamei determină erupția mai timpurie a primului dinte la copil."},{"id":"C","text":"Primii dinți erup mai devreme la fete, însă băieții prezintă un avans pentru secvențele ulterioare."},{"id":"D","text":"O vârstă mai tânără a mamei la momentul nașterii primului copil se corelează cu un moment mai precoce al erupției dentare."},{"id":"E","text":"Ritmul erupției dinților primari în cazul nașterilor premature se compensează în general până la vârsta de 2 ani și jumătate."}],"correct":["A","D","E"],"pages":[369],"source":"set-2"},{"id":"set2-Ir6uprO8","fingerprint":"2815adfcf2586bb1","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care dintre următoarele afirmații descriu corect variațiile fiziologice ale erupției dinților permanenți?","options":[{"id":"A","text":"Întârzierile erupției dentare permanente se înregistrează cu o frecvență mai mare comparativ cu accelerările acesteia."},{"id":"B","text":"Tendința seculară determină erupția mai tardivă a molarilor trei și a primilor premolari maxilari."},{"id":"C","text":"Diferențele de erupție între sexe în perioada pubertății pot atinge 7-8 luni, influențând momentul apariției premolarilor și caninilor."},{"id":"D","text":"Accelerarea erupției este caracteristică populațiilor din zonele cu climat temperat, comparativ cu populațiile din zona tropicală."},{"id":"E","text":"Copiii proveniți din mediul rural prezintă o accelerare a procesului de erupție față de copiii din mediul urban."}],"correct":["A","B","C"],"pages":[369],"source":"set-2"},{"id":"set2-1CK985KL","fingerprint":"19b6539112b34780","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care sunt factorii etiologici implicați în modificările patologice ale ritmului de erupție a dinților permanenți?","options":[{"id":"A","text":"Hiperactivitatea glandei tiroide produce o accelerare a procesului de erupție dentară."},{"id":"B","text":"Traumatismele dento-alveolare urmate de instalarea anchilozei dento-alveolare determină întârzierea erupției dinților succesori."},{"id":"C","text":"Complicațiile gangrenei dinților temporari determină o erupție întârziată a succesorilor permanenți din cauza fibrozării mucoasei."},{"id":"D","text":"Angioamele faciale antrenează accelerarea erupției dinților în zonele interesate prin intermediul creșterii fluxului sanguin local."},{"id":"E","text":"Pierderea extrem de timpurie a unui dinte temporar conduce invariabil la accelerarea erupției dintelui permanent de înlocuire."}],"correct":["A","B","D"],"pages":[370],"source":"set-2"},{"id":"set2-c8n4IP3D","fingerprint":"6da7af8741c7c8e6","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Conform regulilor generale de dinamică și cronologie, care este prima grupă dentară temporară care face excepție de la ordinea de erupție determinată strict de poziția pe arcadă?","options":[{"id":"A","text":"Caninii inferiori"},{"id":"B","text":"Molarii secunzi superiori"},{"id":"C","text":"Primii molari temporari"},{"id":"D","text":"Incisivii laterali superiori"},{"id":"E","text":"Incisivii centrali superiori"}],"correct":["C"],"pages":[370,371,372],"source":"set-2"},{"id":"set2-c9yuL2uC","fingerprint":"309c87c31496042f","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care dintre următoarele afirmații descriu excepțiile de la regulile generale privind dinamica erupției dinților temporari?","options":[{"id":"A","text":"Primii molari temporari își fac apariția pe arcadă înaintea caninilor."},{"id":"B","text":"Incisivii laterali superiori apar în cavitatea bucală înaintea incisivilor laterali inferiori."},{"id":"C","text":"Caninii temporari maxilari erup înaintea primilor molarilor temporari mandibulari."},{"id":"D","text":"Erupția dinților respectă invariabil ordinea poziției lor pe arcadă."},{"id":"E","text":"Dinții temporari mandibulari erup exclusiv înaintea omologilor maxilari, fără excepții."}],"correct":["A","B"],"pages":[370,371,372],"source":"set-2"},{"id":"set2-CpmIgXy0","fingerprint":"856f589c32e32886","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care sunt criteriile temporale care definesc o erupție dentară cu modificări patologice de cronologie?","options":[{"id":"A","text":"Finalizarea erupției tuturor dinților temporari la 2 ani și 2 luni este considerată o erupție întârziată."},{"id":"B","text":"Erupția ultimului dinte temporar înaintea vârstei de 2 ani certifică o erupție precoce."},{"id":"C","text":"O variație de 1-2 luni a erupției în afara intervalelor de referință are o semnificație patologică certă."},{"id":"D","text":"Erupția primului dinte temporar înaintea vârstei de 4 luni definește o erupție precoce."},{"id":"E","text":"Apariția primului dinte temporar după vârsta de 1 an indică o erupție întârziată."}],"correct":["B","D","E"],"pages":[370,371,372],"source":"set-2"},{"id":"set2-CrBE_ZA5","fingerprint":"de7b3df2634d86af","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"În privința cronologiei și a factorilor de influență ai erupției dinților temporari, care dintre următoarele afirmații sunt aplicabile?","options":[{"id":"A","text":"Dinții temporari erup normal în intervalul 6-30 luni, procesul desfășurându-se în trei etape distincte."},{"id":"B","text":"Dezvoltarea dentară intrauterină permite protejarea dinților temporari de către organismul matern, cronologia fiind mai dependentă de factori genetici decât de cei de mediu."},{"id":"C","text":"Conform regulii 6/4, la fiecare interval de 6 luni erup încă 4 dinți temporari."},{"id":"D","text":"În mod fiziologic, la fete primul grup de dinți erupe mai devreme decât la băieți."},{"id":"E","text":"Etapa a III-a de erupție cuprinde apariția caninilor și a molarilor secunzi între 24 și 30 de luni."}],"correct":["A","B","C"],"pages":[370,371,372],"source":"set-2"},{"id":"set2-qRLT2Mis","fingerprint":"df50f74ec788d2eb","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Referitor la datele medii utilizate în România privind vârstele de erupție ale dinților temporari, care asocieri cronologice sunt valide?","options":[{"id":"A","text":"Caninul inferior are o vârstă medie de erupție de 19 luni (1 an și 7 luni)."},{"id":"B","text":"Incisivul central superior erupe, în medie, la vârsta de 10 luni."},{"id":"C","text":"Incisivul lateral superior erupe ulterior incisivului lateral inferior."},{"id":"D","text":"Molarii secunzi superiori erup primii din grupa lor, la vârsta de 24 de luni."},{"id":"E","text":"Molarul I inferior erupe la 16 luni (1 an și 4 luni)."}],"correct":["A","B","E"],"pages":[370,371,372],"source":"set-2"},{"id":"set2-3PWv5xd1","fingerprint":"bba76e8d4c997201","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care dintre următorii factori sunt asociați etiologic cu erupția precoce sub forma dinților natali și neonatali?","options":[{"id":"A","text":"Tulburările endocrine."},{"id":"B","text":"Deficiențele alimentare."},{"id":"C","text":"Luesul dobândit în perioada neonatală."},{"id":"D","text":"Poziția profundă a germenului dentar intraosos."},{"id":"E","text":"Dezvoltarea foarte rapidă a germenului dentar."}],"correct":["A","B","E"],"pages":[373],"source":"set-2"},{"id":"set2-MuPsI7CB","fingerprint":"c66d0b56b435e178","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Referitor la regulile de erupție a dinților permanenți, care dintre afirmațiile următoare sunt adevărate?","options":[{"id":"A","text":"Segmentul cel mai perturbat ca ordine și cronologie a erupției este cel al incisivilor."},{"id":"B","text":"În cadrul aceluiași grup dentar, erupția dinților inferiori o precede pe cea a celor superiori, cu excepția premolarilor maxilari."},{"id":"C","text":"Primul dinte care erupe pe arcadă este primul molar inferior."},{"id":"D","text":"La băieți, erupția dinților permanenți se desfășoară mai repede comparativ cu fetele."},{"id":"E","text":"Factorii de mediu influențează semnificativ cronologia erupției, generând variații numeroase, în special în etapa a doua."}],"correct":["B","C","E"],"pages":[373],"source":"set-2"},{"id":"set2-Unp_56f6","fingerprint":"7e06769541978d1b","chapterId":"set-2","subchapterId":"set2-5.01","type":"CS","text":"Care este secvența corectă a erupției dinților permanenți în sectorul premolar-canin la băieți, pe arcada maxilară?","options":[{"id":"A","text":"Caninul, primul premolar, al doilea premolar."},{"id":"B","text":"Al doilea premolar, primul premolar, caninul."},{"id":"C","text":"Primul premolar, caninul, al doilea premolar."},{"id":"D","text":"Al doilea premolar, caninul, primul premolar."},{"id":"E","text":"Primul premolar, al doilea premolar, caninul."}],"correct":["E"],"pages":[373],"source":"set-2"},{"id":"set2-sSIzpoAk","fingerprint":"d1c50f8cf2411b4a","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Ce trăsături clinice, patogenice și radiologice caracterizează sechestrul de erupție?","options":[{"id":"A","text":"Afectează cu predilecție molarii permanenți și molarii II temporari."},{"id":"B","text":"Este provocat de neconcordanța dintre viteza redusă de erupție dentară și viteza accelerată de resorbție a osului."},{"id":"C","text":"Este constituit dintr-un fragment osos localizat pe fața ocluzală a unui molar aflat în erupție."},{"id":"D","text":"Din punct de vedere clinic, este frecvent simptomatic, producând algii intense continue în repaus."},{"id":"E","text":"Diagnosticul radiografic evidențiază o radioopacitate separată de dinte printr-o zonă de radiotransparență."}],"correct":["A","C","E"],"pages":[375],"source":"set-2"},{"id":"set2-ppqqnZas","fingerprint":"0d4d03d5a095bdf7","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care dintre următoarele modificări se observă la sfârșitul perioadei dentiției temporare, premergător erupției dinților permanenți?","options":[{"id":"A","text":"Instalarea abraziunii fiziologice la nivelul arcadelor dentare."},{"id":"B","text":"Apariția tremelor între dinți, fenomen denumit diastemizare."},{"id":"C","text":"Micșorarea arcului frontal prin dispariția spațiilor interdentare."},{"id":"D","text":"O ușoară mezializare a mandibulei, favorizând stabilirea relațiilor interarcadice normale la nivelul dinților permanenți."},{"id":"E","text":"O ușoară distalizare a mandibulei, care previne angrenajele inverse."}],"correct":["A","B","D"],"pages":[373],"source":"set-2"},{"id":"set2-SDU6iQ2q","fingerprint":"f0bbe190d3048399","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Privind tabloul clinic și atitudinea terapeutică în gingivostomatita asociată erupției, care sunt afirmațiile valabile?","options":[{"id":"A","text":"Tratamentul medicamentos exclude administrarea antibioticelor pe cale sistemică, indiferent de gravitatea cazului."},{"id":"B","text":"Terapia locală presupune utilizarea unor colutorii care conțin antibiotice, corticosteroizi și vitamine."},{"id":"C","text":"Evoluția poate progresa de la o gingivită eritematoasă simplă către forme pultacee, ulceroase sau ulcero-necrotice."},{"id":"D","text":"Igienizarea riguroasă a cavității bucale prin clătiri locale face parte din conduita de primă intenție."},{"id":"E","text":"Atitudinea terapeutică interzice strict igienizarea locală în formele ulcerative pentru a preveni extinderea leziunilor."}],"correct":["B","C","D"],"pages":[375],"source":"set-2"},{"id":"set2-H-IGKpQY","fingerprint":"48b0f98abfbbf61a","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"În contextul vârstelor medii de erupție din etapa I a dentiției permanente, care sunt asocierile cronologice exacte?","options":[{"id":"A","text":"Primii molari erup cel mai târziu în cadrul etapei I, între 8-9 ani."},{"id":"B","text":"Incisivii centrali superiori și incisivii laterali inferiori erup la vârsta de 7-8 ani."},{"id":"C","text":"Incisivii laterali inferiori erup primii pe arcadă, în intervalul 6-7 ani."},{"id":"D","text":"Primii molari și incisivii centrali inferiori erup la vârsta de 6-7 ani."},{"id":"E","text":"Incisivii laterali superiori erup în intervalul de vârstă 8-9 ani."}],"correct":["B","D","E"],"pages":[373],"source":"set-2"},{"id":"set2-TIT-KQC-","fingerprint":"56df5461f830536d","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care sunt variantele posibile de modificare a ordinii de erupție în etapa I a dentiției permanente?","options":[{"id":"A","text":"Incisivii centrali inferiori erup după incisivii centrali superiori."},{"id":"B","text":"Incisivii laterali superiori erup constant înaintea primilor molari permanenți."},{"id":"C","text":"Incisivii centrali inferiori erup înaintea primilor molari de 6 ani."},{"id":"D","text":"Primii molari erup înaintea incisivilor centrali inferiori."},{"id":"E","text":"Primii molari erup complet simultan cu incisivii centrali inferiori."}],"correct":["A","C","D","E"],"pages":[373],"source":"set-2"},{"id":"set2-EJh-55o9","fingerprint":"d74164f601d34d1e","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care sunt afirmațiile corecte referitoare la criteriile și parametrii utilizați în diagnosticul tulburărilor vârstei de erupție dentară?","options":[{"id":"A","text":"Erupția cronologic întârziată poate afecta un singur dinte, un grup de dinți sau întreaga serie dentară."},{"id":"B","text":"Erupția cronologic accelerată implică apariția dinților la momente de timp plasate cu mai mult de 2 x deviația standard peste vârsta medie de erupție."},{"id":"C","text":"Erupția cronologic normală se definește prin apariția dinților în intervalul de variabilitate de +/- 2 x deviația standard față de vârsta medie de erupție."},{"id":"D","text":"Diagnosticul tulburărilor vârstei de erupție utilizează concomitent criteriul cronologic și criteriul dezvoltării radiculare."},{"id":"E","text":"Deviația standard considerată normală pentru erupția dinților temporari este cuprinsă între 6 luni și un an și jumătate."}],"correct":["A","C","D"],"pages":[375],"source":"set-2"},{"id":"set2-LB1b6N9y","fingerprint":"b5eeb5844e4b84ec","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care dintre următoarele aspecte reprezintă tulburări ale ordinii de erupție specifice primei etape a dentiției mixte?","options":[{"id":"A","text":"Migrarea mezială a primului molar permanent favorizată de osteofibrozele postextracționale."},{"id":"B","text":"Erupția incisivilor laterali înaintea unuia sau ambilor centrali."},{"id":"C","text":"Erupția primilor premolari înaintea incisivilor laterali."},{"id":"D","text":"Asimetrii în erupția incisivilor centrali superiori."},{"id":"E","text":"Erupția celui de-al doilea premolar înaintea primului premolar și a caninului."}],"correct":["B","C","D"],"pages":[375],"source":"set-2"},{"id":"set2-40rRDlkb","fingerprint":"252529881db74b9f","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care sunt aspectele decelabile pe examenul radiologic care justifică tulburările ordinii de erupție în prima etapă a dentiției mixte?","options":[{"id":"A","text":"Apariția cudurilor corono-radiculare."},{"id":"B","text":"Lipsa mugurelui dentar."},{"id":"C","text":"Prezența rizalizei accelerate la nivelul dinților temporari."},{"id":"D","text":"Formarea unor osteoscleroze secundare complicațiilor periapicale ale molarilor temporari."},{"id":"E","text":"Existența unor dinți supranumerari ce acționează ca obstacole locale."}],"correct":["A","B","E"],"pages":[375],"source":"set-2"},{"id":"set2-P14f3T09","fingerprint":"6337100a6b075eef","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care dintre următoarele enunțuri descriu în mod obiectiv tulburările de poziție ale dinților?","options":[{"id":"A","text":"Transpoziția implică schimbarea locului pe arcadă între doi dinți vecini, caninul superior schimbându-și cel mai frecvent locul cu primul premolar."},{"id":"B","text":"Caninul superior își schimbă frecvent locul pe arcadă cu incisivul central, proces denumit transpoziție dentară."},{"id":"C","text":"Malpozițiile dentare interesează în mod caracteristic ultimii dinți din grup, precum caninul superior, premolarul 2 inferior și molarul 3."},{"id":"D","text":"Molarul de minte inferior situat în ramura ascendentă este un exemplu de ectopie dentară."},{"id":"E","text":"Heterotopia reprezintă situația în care dintele se formează și se află la mare distanță de locul său obișnuit pe arcadă."}],"correct":["A","C","E"],"pages":[376],"source":"set-2"},{"id":"set2-gGrHJW6R","fingerprint":"2f5e647d17a2865a","chapterId":"set-2","subchapterId":"set2-5.01","type":"CM","text":"Care sunt caracteristicile clinice și manifestările asociate tulburărilor de ritm ale erupției dentare?","options":[{"id":"A","text":"Întârzierea debutului erupției dinților temporari la 9-10 luni este urmată de un ritm de erupție lent, toți dinții fiind prezenți abia la 3 ani."},{"id":"B","text":"Erupția dinților pe o hemiarcadă atinge planul de ocluzie în timp ce dinții de pe hemiarcada contralaterală se află în infraocluzie."},{"id":"C","text":"Vârsta dentară prezintă un decalaj față de vârsta osoasă, care se poate manifesta prin erupția accelerată a incisivilor."},{"id":"D","text":"Permutarea dentară se desfășoară cu apariția primilor premolari înaintea incisivilor laterali din cauza lipsei tremelor și diastemelor fiziologice."},{"id":"E","text":"Maxilarul insuficient dezvoltat cumulat cu erupția accelerată a incisivilor generează o dizarmonie dento-alveolară cu înghesuire tranzitorie."}],"correct":["B","C","E"],"pages":[376],"source":"set-2"}];
